    make_textbook_entry(RENAISSANCE_REFORMATION, tags=["ルネサンス", "宗教改革", "ダンテ", "レオナルド", "ミケランジェロ", "グーテンベルク", "ルター", "カルヴァン", "英国国教会", "イエズス会"]),
    make_textbook_entry(DAIKOUKAI, tags=["大航海時代", "ポルトガル", "スペイン", "コロンブス", "ヴァスコ=ダ=ガマ", "マゼラン", "コルテス", "ピサロ", "トルデシリャス条約", "ポトシ銀山", "価格革命"]),
    make_textbook_entry(ZETTAISHUGI, tags=["絶対主義", "王権神授説", "ルイ14世", "ヴェルサイユ", "コルベール", "重商主義", "フリードリヒ大王", "マリア=テレジア", "ピョートル大帝", "エカチェリーナ", "啓蒙専制"]),
